void _fastcall win_SetObjSelectedState(int obj, int selected)
{
    unsigned char far *o;

    win_LockWin(obj);
    o = (unsigned char far *)win_ObjAddr(obj);
    if (o[0x24] & 0x20)
        win_SetGroupSelectedState(obj, o[0x20], 0);
    win_SetObjSelectedStateI(obj, selected);
    win_UnlockWin(obj);
}
